"""A standalone file-copy command, implemented from observed CLI behavior."""
import errno
import fcntl
import fnmatch
import math
import os
import re
import stat
import sys
import time

from helptext import LONG_HELP, SHORT_HELP


class Exit(Exception):
    def __init__(self, code=1):
        self.code = code


class CopyFailure(Exception):
    def __init__(self, detail, phase='copy'):
        self.detail = detail
        self.phase = phase


def write(text, stream=None):
    if stream is None:
        stream = sys.stdout
    stream.write(text)
    stream.flush()


def fatal(text):
    write('Error: ' + text + '\n', sys.stderr)
    raise Exit(1)


def os_error(e):
    return '{} (os error {})'.format(os.strerror(e.errno), e.errno)


def quoted(s):
    """Rust-style debug formatting for a filesystem path."""
    result = '"'
    for c in s:
        if c == '\\':
            result += '\\\\'
        elif c == '"':
            result += '\\"'
        elif c == '\n':
            result += '\\n'
        elif c == '\r':
            result += '\\r'
        elif c == '\t':
            result += '\\t'
        elif c == '\0':
            result += '\\0'
        elif not c.isprintable():
            result += '\\u{' + format(ord(c), 'x') + '}'
        else:
            result += c
    return result + '"'


def path_parts(path):
    # Path comparisons do not canonicalize symlinks or remove '..'.  A leading
    # './' is a component, while inner '.' and trailing slashes are ignored.
    result = []
    if path.startswith('/'):
        result.append('/')
    elif path == '.' or path.startswith('./'):
        result.append('.')
    result.extend(p for p in path.split('/') if p and p != '.')
    return result


def path_equal(a, b):
    return path_parts(a) == path_parts(b)


def filename(path):
    parts = path_parts(path)
    if parts and parts[-1] not in ('/', '.', '..'):
        return parts[-1]
    return None


def path_join(base, tail):
    if not tail:
        return base
    if tail.startswith('/') or not base:
        return tail
    return base + ('' if base.endswith('/') else '/') + tail


# The command-line parser deliberately keeps parsing separate from execution:
# even invalid source lists must not produce filesystem side effects.
OPTIONS = [
    ('verbose', 'v', None),
    ('recursive', 'r', None),
    ('dereference', 'L', None),
    ('workers', 'w', 'WORKERS'),
    ('block-size', None, 'BLOCK_SIZE'),
    ('no-clobber', 'n', None),
    ('force', 'f', None),
    ('gitignore', None, None),
    ('glob', 'g', None),
    ('no-progress', None, None),
    ('no-perms', None, None),
    ('no-timestamps', None, None),
    ('ownership', 'o', None),
    ('driver', None, 'DRIVER'),
    ('no-target-directory', 'T', None),
    ('target-directory', None, 'TARGET_DIRECTORY'),
    ('fsync', None, None),
    ('reflink', None, 'REFLINK'),
    ('backup', None, 'BACKUP'),
    ('help', 'h', None),
    ('version', 'V', None),
]
LONGS = {x[0]: x for x in OPTIONS}
SHORTS = {x[1]: x for x in OPTIONS if x[1]}


def option_repr(name):
    s = '--' + name
    if name == 'verbose':
        s += '...'
    if LONGS[name][2]:
        s += ' <' + LONGS[name][2] + '>'
    return s


def jaro_winkler(a, b):
    if a == b:
        return 1.0
    if not a or not b:
        return 0.0
    span = max(max(len(a), len(b)) // 2 - 1, 0)
    hit_a, hit_b = [False] * len(a), [False] * len(b)
    hits = 0
    for i, c in enumerate(a):
        for j in range(max(0, i-span), min(len(b), i+span+1)):
            if not hit_b[j] and c == b[j]:
                hit_a[i] = hit_b[j] = True
                hits += 1
                break
    if not hits:
        return 0.0
    aa = [c for c, yes in zip(a, hit_a) if yes]
    bb = [c for c, yes in zip(b, hit_b) if yes]
    trans = sum(c != d for c, d in zip(aa, bb)) / 2
    score = (hits/len(a) + hits/len(b) + (hits-trans)/hits) / 3
    if score > 0.7:
        prefix = 0
        for c, d in zip(a[:4], b[:4]):
            if c != d:
                break
            prefix += 1
        score += prefix * 0.1 * (1-score)
    return score


class Parser:
    def __init__(self, program):
        self.program = program
        self.seen = []
        self.paths = []
        self.values = {'verbose': 0, 'workers': 4, 'block-size': 1048576,
                       'driver': 'parfile', 'reflink': 'auto', 'backup': 'none'}

    def usage(self, options=None):
        return 'Usage: ' + self.program + (' ' + ' '.join(options) if options else ' [OPTIONS]') + ' [PATHS]...'

    def error(self, text, usage=False, tip=None):
        msg = 'error: ' + text + '\n\n'
        if tip:
            msg += '  tip: ' + tip + '\n\n'
        if usage:
            msg += (self.usage() if usage is True else usage) + '\n\n'
        msg += "For more information, try '--help'.\n"
        write(msg, sys.stderr)
        raise Exit(2)

    def unexpected(self, arg):
        candidate = None
        if arg.startswith('--'):
            name = arg[2:]
            scores = [(jaro_winkler(name, n), n) for n in LONGS]
            score, best = max(scores)
            if score > 0.8:
                candidate = best
        if candidate:
            usageopts = [option_repr(n) for n in self.seen if n not in ('help', 'version')]
            if candidate not in self.seen:
                usageopts.append(option_repr(candidate))
            self.error("unexpected argument '{}' found".format(arg), self.usage(usageopts),
                       "a similar argument exists: '--{}'".format(candidate))
        self.error("unexpected argument '{}' found".format(arg), True,
                   "to pass '{}' as a value, use '-- {}'".format(arg, arg))

    def invalid(self, name, value, explanation):
        self.error("invalid value '{}' for '{}': {}".format(value, option_repr(name), explanation))

    def value(self, name, text):
        if name == 'workers':
            if not text:
                self.invalid(name, text, 'cannot parse integer from empty string')
            if not re.fullmatch(r'\+?[0-9]+', text):
                self.invalid(name, text, 'invalid digit found in string')
            number = int(text)
            if number > 18446744073709551615:
                self.invalid(name, text, 'number too large to fit in target type')
            return number
        if name in ('driver', 'reflink', 'backup'):
            value = text.lower()
            allowed = {'driver': ('parfile', 'parblock'),
                       'reflink': ('auto', 'always', 'never'),
                       'backup': ('none', 'off', 'numbered', 'auto')}
            if value not in allowed[name]:
                if name == 'driver':
                    self.invalid(name, text, 'Unknown driver: ' + text)
                self.invalid(name, text, "Invalid arguments: Unexpected value for '{}': {}".format(name, text))
            return value
        if name == 'block-size':
            return self.byte_size(text)
        return text

    def byte_size(self, original):
        s = original.strip().lower()
        if not s:
            write("\nthread 'main' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/unbytify-0.2.0/src/lib.rs:101:14:\nbyte index 1 is out of bounds of ``\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n".format(os.getpid()), sys.stderr)
            raise Exit(101)
        def bad(reason='could not interpret string as byte size'):
            self.invalid('block-size', original, reason)
        # Bare values must be whole numbers.  A unit suffix permits fractions.
        if s.startswith('-'):
            bad()
        try:
            if '_' in s:
                raise ValueError()
            value = float(s)
            if not math.isfinite(value):
                return 0 if math.isnan(value) else 18446744073709551615
            if value >= 0 and value == math.floor(value):
                return min(int(value), 18446744073709551615)
        except ValueError:
            pass
        m = re.fullmatch(r'(.*?)\s*([kmgtpe]?)(i?b|[kmgtpe])', s)
        # Separate the suffix from the floating point number, allowing decimal
        # and scientific notation and all observed binary size abbreviations.
        m = re.fullmatch(r'(.+?)\s*(kib|mib|gib|tib|pib|eib|kb|mb|gb|tb|pb|eb|k|m|g|t|p|e|b)', s)
        if not m:
            bad()
        try:
            numeric = m[1].strip()
            if '_' in numeric:
                bad()
            value = float(numeric)
        except ValueError:
            bad()
        unit = m[2]
        power = 0 if unit == 'b' else 'kmgtpe'.index(unit[0]) + 1
        value *= 1024 ** power
        if value < 0:
            bad()
        if math.isinf(value) or value > 18446744073709551615:
            bad('byte size too large')
        if math.isnan(value):
            return 0
        return int(value)

    def accept(self, name, supplied, spelling):
        if name in self.seen and name != 'verbose':
            self.error("the argument '{}' cannot be used multiple times".format(option_repr(name)), True)
        if LONGS[name][2]:
            if supplied is None:
                self.error("a value is required for '{}' but none was supplied".format(option_repr(name)))
            self.values[name] = self.value(name, supplied)
        else:
            if supplied is not None:
                self.error("unexpected value '{}' for '{}' found; no more were expected".format(supplied, option_repr(name)),
                           self.usage([option_repr(n) for n in self.seen] + [option_repr(name)]))
            if name == 'help':
                text = LONG_HELP if spelling.startswith('--') else SHORT_HELP
                write(text.replace('Usage: executable', 'Usage: ' + self.program))
                raise Exit(0)
            if name == 'version':
                write('xcp 0.24.3\n')
                raise Exit(0)
            if name == 'verbose':
                self.values[name] = min(255, self.values[name] + 1)
            else:
                self.values[name] = True
        if name not in self.seen:
            self.seen.append(name)

    def parse(self, argv):
        i = 0
        positional = False
        while i < len(argv):
            arg = argv[i]
            if positional or arg == '-' or not arg.startswith('-'):
                self.paths.append(arg)
            elif arg == '--':
                positional = True
            elif arg.startswith('--'):
                option, sep, val = arg[2:].partition('=')
                if option not in LONGS:
                    self.unexpected('--' + option)
                if LONGS[option][2] and not sep:
                    if i + 1 < len(argv) and (not argv[i+1].startswith('-') or argv[i+1] == '-'):
                        i += 1
                        val = argv[i]
                    else:
                        # A short unknown flag wins over a missing-value error.
                        if i+1 < len(argv) and argv[i+1].startswith('-') and not argv[i+1].startswith('--') and len(argv[i+1]) > 1:
                            c = argv[i+1][1]
                            if c not in SHORTS:
                                self.unexpected('-' + c)
                        val = None
                elif not sep:
                    val = None
                self.accept(option, val, '--' + option)
            else:
                j = 1
                while j < len(arg):
                    c = arg[j]
                    if c not in SHORTS:
                        self.unexpected('-' + c)
                    option = SHORTS[c][0]
                    val = None
                    if LONGS[option][2]:
                        if j + 1 < len(arg):
                            val = arg[j+1:]
                            if val.startswith('='):
                                val = val[1:]
                        elif i+1 < len(argv) and (not argv[i+1].startswith('-') or argv[i+1] == '-'):
                            i += 1
                            val = argv[i]
                        elif i+1 < len(argv) and len(argv[i+1]) > 1 and argv[i+1][1] != '-' and argv[i+1][1] not in SHORTS:
                            self.unexpected('-' + argv[i+1][1])
                        j = len(arg)
                    self.accept(option, val, '-' + c)
                    j += 1
            i += 1
        return self.values, self.paths


class Logger:
    def __init__(self, verbosity):
        self.verbosity = verbosity

    def line(self, level, message):
        write(time.strftime('%H:%M:%S', time.gmtime()) + ' [' + level + '] ' + message + '\n',
              sys.stderr if level == 'ERROR' else sys.stdout)

    def info(self, text):
        if self.verbosity:
            self.line('INFO', text)

    def debug(self, thread, module, text):
        if self.verbosity >= 2:
            self.line('DEBUG', '({}) {}: {}'.format(thread, module, text))


# Native globs differ slightly from shell globs: they include dotfiles, do not
# interpret braces or backslash escapes, and permit a whole-component '**'.
def validate_glob(pattern):
    i = 0
    while i < len(pattern):
        if pattern[i] == '[':
            j = i+1
            if j < len(pattern) and pattern[j] == '!':
                j += 1
            if j < len(pattern) and pattern[j] == ']':
                j += 1
            k = pattern.find(']', j)
            if k < 0:
                fatal('Pattern syntax error near position {}: invalid range pattern'.format(i))
            i = k+1
        elif pattern[i:i+2] == '**':
            if i+2 < len(pattern) and pattern[i+2] == '*':
                fatal('Pattern syntax error near position {}: wildcards are either regular `*` or recursive `**`'.format(i+2))
            if i and pattern[i-1] != '/':
                fatal('Pattern syntax error near position {}: recursive wildcards must form a single path component'.format(i-1))
            if i+2 < len(pattern) and pattern[i+2] != '/':
                fatal('Pattern syntax error near position {}: recursive wildcards must form a single path component'.format(i+2))
            i += 2
        else:
            i += 1


def expand_glob(pattern):
    validate_glob(pattern)
    absolute = pattern.startswith('/')
    parts = [p for p in pattern.split('/') if p and p != '.']
    results = []
    trailing_slash = pattern.endswith('/')

    def entries(base):
        try:
            return sorted(os.listdir(base or '.'))
        except OSError:
            return []

    def visit(base, idx, parents):
        if idx == len(parts):
            if os.path.lexists(base or '.') and (not trailing_slash or os.path.isdir(base or '.')):
                results.append(base or '.')
            return
        p = parts[idx]
        if p == '**':
            if idx+1 < len(parts):
                visit(base, idx+1, parents)
            for name in entries(base):
                child = path_join(base, name)
                if not os.path.isdir(child):
                    continue
                try:
                    st = os.stat(child)
                except OSError:
                    continue
                inode = (st.st_dev, st.st_ino)
                if inode in parents:
                    continue
                if idx+1 == len(parts):
                    results.append(child)
                visit(child, idx, parents | {inode})
            return
        wild = any(c in p for c in '*?[')
        if not wild:
            child = path_join(base, p)
            if idx+1 == len(parts) or os.path.isdir(child):
                visit(child, idx+1, parents)
            return
        names = entries(base)
        # Explicit leading dots also match the synthetic parent/current entries.
        if p.startswith('.'):
            names = ['..', '.'] + names
        for name in names:
            if fnmatch.fnmatchcase(name, p):
                child = path_join(base, name)
                if not base and name in ('.', '..'):
                    child = './' + name
                if idx+1 == len(parts) or os.path.isdir(child):
                    visit(child, idx+1, parents)
    if not parts:
        if os.path.lexists(pattern):
            return [pattern.rstrip('/') or '/']
        return []
    visit('/' if absolute else '', 0, set())
    return results


def ignore_regex(pattern):
    """Translate the small gitignore pattern language, keeping slash boundaries."""
    out = ''
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '\\' and i+1 < len(pattern):
            i += 1
            out += re.escape(pattern[i])
        elif c == '*':
            if pattern[i:i+2] == '**':
                if i+2 < len(pattern) and pattern[i+2] == '/':
                    out += '(?:.*/)?'
                    i += 2
                else:
                    out += '.*'
                    i += 1
            else:
                out += '[^/]*'
        elif c == '?':
            out += '[^/]'
        elif c == '[':
            end = pattern.find(']', i+1)
            if end < 0:
                return None
            chars = pattern[i+1:end]
            if chars.startswith('!'):
                chars = '^' + chars[1:]
            elif chars.startswith('^'):
                chars = '\\' + chars
            out += '[' + chars + ']'
            i = end
        elif c == '{':
            out += '(?:'
        elif c == '}':
            out += ')'
        elif c == ',' and '{' in pattern:
            out += '|'
        else:
            out += re.escape(c)
        i += 1
    try:
        return re.compile('^' + out + '$')
    except re.error:
        return None


class IgnoreRules:
    def __init__(self, root, enabled):
        self.root = root
        self.rules = []
        if not enabled or not os.path.isdir(root):
            return
        try:
            with open(path_join(root, '.gitignore'), encoding='utf-8') as f:
                lines = f.read().splitlines()
        except (OSError, UnicodeError):
            return
        for line in lines:
            if not line or line.startswith('#'):
                continue
            line = re.sub(r'(?<!\\)\s+$', '', line)
            if not line:
                continue
            negate = line.startswith('!')
            if negate:
                line = line[1:]
            directory = line.endswith('/')
            if directory:
                line = line[:-1]
            anchored = line.startswith('/')
            if anchored:
                line = line[1:]
            if not line:
                continue
            basename = not anchored and '/' not in line
            regex = ignore_regex(line)
            if regex:
                self.rules.append((regex, basename, directory, negate))

    def ignores(self, relative, isdir):
        # The root entry is visited too; name-only rules can exclude it.
        subject = relative if relative else (filename(self.root) or '')
        ignored = False
        for regex, basename, directory, negate in self.rules:
            if directory and not isdir:
                continue
            name = subject.rsplit('/', 1)[-1] if basename else subject
            if regex.fullmatch(name):
                ignored = not negate
        return ignored


class Copier:
    def __init__(self, opts):
        self.opts = opts
        self.log = Logger(opts['verbose'])
        self.block = opts['block-size']
        self.parblock = opts['driver'] == 'parblock'
        self.copy_thread = 3 if self.parblock else 4
        self.walk_thread = 4 if self.parblock else 3
        self.worker_started = False
        self.failed = None
        self.pending = []

    def flag(self, name):
        return self.opts.get(name, False)

    def debug_walk(self, msg):
        self.log.debug(self.walk_thread, 'libxcp::operations', msg)

    def debug_copy(self, msg, module='libxcp::operations'):
        self.log.debug(self.copy_thread, module, msg)

    def preflight(self, sources, dest):
        if not sources:
            fatal('Invalid source: No source files found.')
        isdestdir = os.path.isdir(dest)
        if len(sources) > 1 and not isdestdir:
            fatal('Invalid destination: Multiple sources and destination is not a directory.')
        if len(sources) == 1 and os.path.isdir(sources[0]) and os.path.isfile(dest):
            fatal('Invalid destination: Cannot copy a directory to a file.')
        pairs = []
        for source in sources:
            self.log.info('Copying source {} to {}'.format(quoted(source), quoted(dest)))
            if not os.path.exists(source):
                fatal('Invalid source: Source does not exist.')
            if os.path.isdir(source) and not self.flag('recursive'):
                fatal('Invalid source: Source is directory and --recursive not specified.')
            if path_equal(source, dest):
                fatal('Invalid source: Cannot copy a directory into itself')
            target = dest
            if isdestdir and not self.flag('no-target-directory'):
                name = filename(source)
                if name is None:
                    fatal('Invalid source: Cannot determine source file name')
                target = path_join(dest, name)
                if path_equal(source, target):
                    fatal('Invalid source: Source is same as destination')
            pairs.append((source, target))
        return pairs

    def destination_exists(self, target):
        return self.flag('no-clobber') and os.path.exists(target)

    def mkdir(self, target):
        self.debug_walk('Creating target directory ' + quoted(target))
        try:
            os.makedirs(target, exist_ok=True)
        except OSError as e:
            message = 'Error creating target directory: ' + os_error(e)
            self.log.line('ERROR', message)
            fatal('Error during copy: ' + message)

    def walk(self, source, target):
        ignore = IgnoreRules(source, self.flag('gitignore'))
        self.debug_walk('Target base is ' + quoted(target))
        # Iterative DFS retains native directory ordering and avoids a recursion
        # limit for very deep directory trees.
        stack = [(source, target, '', True, set())]
        while stack:
            src, dst, rel, root, ancestors = stack.pop()
            try:
                lst = os.lstat(src)
            except OSError as e:
                fatal('IO error for operation on {}: {}\n\nCaused by:\n    {}'.format(src, os_error(e), os_error(e)))
            self.debug_walk('Got tree entry Ok(DirEntry({}))'.format(quoted(src)))
            typemode = lst.st_mode
            follow_root_dir = root and stat.S_ISLNK(typemode) and os.path.isdir(src)
            isdir = stat.S_ISDIR(typemode) or follow_root_dir
            actual = src
            if self.flag('dereference'):
                try:
                    actual = os.path.realpath(src, strict=True)
                    st = os.stat(actual)
                except OSError as e:
                    fatal(os_error(e))
                typemode = st.st_mode
                isdir = stat.S_ISDIR(typemode)
            else:
                st = lst
            if ignore.ignores(rel, isdir):
                continue
            if self.destination_exists(dst):
                message = 'Destination Exists: Destination file exists and --no-clobber is set., ' + dst
                self.log.line('ERROR', 'Received error: ' + message)
                fatal(message)
            if stat.S_ISLNK(typemode):
                try:
                    link = os.readlink(src)
                except OSError as e:
                    fatal(os_error(e))
                self.queue(('Symlink', link, dst, lst))
            elif stat.S_ISDIR(typemode):
                self.mkdir(dst)
            elif stat.S_ISREG(typemode):
                self.debug_walk('Send copy operation {} to {}'.format(quoted(actual), quoted(dst)))
                self.queue(('Copy', actual, dst, st))
            else:
                self.queue(('Special', actual, dst, st))
            if isdir:
                try:
                    dstat = os.stat(src)
                    ident = (dstat.st_dev, dstat.st_ino)
                    if self.flag('dereference') and ident in ancestors:
                        fatal('File system loop found: {} points to an ancestor'.format(src))
                    with os.scandir(src) as entries:
                        names = [ent.name for ent in entries]
                except OSError as e:
                    fatal('IO error for operation on {}: {}\n\nCaused by:\n    {}'.format(src, os_error(e), os_error(e)))
                for name in reversed(names):
                    stack.append((path_join(src, name), path_join(dst, name),
                                  path_join(rel, name), False, ancestors | {ident}))

    def queue(self, op):
        # Copies are independent work items.  Processing in visitation order is
        # deterministic and has the same data and metadata effects as the pool.
        self.perform(op)

    def backup(self, target):
        mode = self.opts['backup']
        if mode in ('none', 'off') or not os.path.exists(target):
            return
        parent = os.path.dirname(target) or '.'
        name = os.path.basename(target)
        prefix = name + '.~'
        maxnum = 0
        try:
            for entry in os.listdir(parent):
                if entry.startswith(prefix) and entry.endswith('~'):
                    n = entry[len(prefix):-1]
                    if re.fullmatch(r'\+?[0-9]+', n):
                        value = int(n)
                        if value <= 18446744073709551615:
                            maxnum = max(maxnum, value)
        except OSError as e:
            raise CopyFailure(os_error(e), 'dispatch')
        if mode == 'auto' and not maxnum:
            return
        new = target + '.~' + str(maxnum+1) + '~'
        self.log.info('Backup: Rename {} to {}'.format(quoted(target), quoted(new)))
        try:
            os.rename(target, new)
        except OSError as e:
            raise CopyFailure(os_error(e), 'dispatch')

    def file_description(self, fd, path, read):
        try:
            canonical = os.readlink('/proc/self/fd/' + str(fd))
        except OSError:
            canonical = os.path.abspath(path)
        return 'File {{ fd: {}, path: {}, read: {}, write: {} }}'.format(fd, quoted(canonical), str(read).lower(), str(not read).lower())

    def copy_range(self, infd, outfd, start, length):
        at = start
        remaining = length
        while remaining:
            count = min(remaining, self.block or remaining, 1073741824)
            try:
                done = os.copy_file_range(infd, outfd, count, at, at)
            except OSError as e:
                if e.errno not in (errno.EXDEV, errno.ENOSYS, errno.EOPNOTSUPP):
                    raise
                data = os.pread(infd, min(count, 1024*1024), at)
                if not data:
                    return
                done = 0
                while done < len(data):
                    done += os.pwrite(outfd, data[done:], at+done)
            if not done:
                return
            remaining -= done
            at += done

    def data_copy(self, infd, outfd, st):
        if st.st_size == 0:
            return
        # File allocation is a better sparse-file test than looking for zeroes:
        # allocated zero-filled blocks must stay allocated.
        if st.st_blocks * 512 < st.st_size:
            offset = 0
            while offset < st.st_size:
                try:
                    start = os.lseek(infd, offset, os.SEEK_DATA)
                except OSError as e:
                    if e.errno == errno.ENXIO:
                        break
                    if e.errno == errno.EINVAL:
                        self.copy_range(infd, outfd, offset, st.st_size-offset)
                        break
                    raise
                end = min(os.lseek(infd, start, os.SEEK_HOLE), st.st_size)
                self.copy_range(infd, outfd, start, end-start)
                offset = end
        else:
            self.copy_range(infd, outfd, 0, st.st_size)

    def attributes(self, infd, outfd, st):
        if not self.flag('no-perms'):
            self.debug_copy('Starting xattr copy...', 'libfs::common')
            try:
                attrs = os.listxattr(infd)
            except OSError as e:
                if e.errno in (errno.ENOTSUP, errno.EOPNOTSUPP):
                    attrs = []
                else:
                    raise
            for attr in attrs:
                self.debug_copy('Copy xattr ' + quoted(attr), 'libfs::common')
                try:
                    os.setxattr(outfd, attr, os.getxattr(infd, attr))
                except OSError as e:
                    # Security labels can be readable while not settable by
                    # the caller; existing labels need not be rewritten.
                    if e.errno in (errno.EPERM, errno.EACCES, errno.ENOTSUP, errno.EOPNOTSUPP):
                        continue
                    raise
            self.debug_copy('Performing permissions copy', 'libfs::common')
            os.fchmod(outfd, stat.S_IMODE(st.st_mode))
        if self.flag('ownership'):
            try:
                os.fchown(outfd, st.st_uid, st.st_gid)
            except OSError as e:
                self.log.line('WARN', 'Failed to copy ownership: ' + os_error(e))
        if not self.flag('no-timestamps'):
            self.debug_copy('Performing timestamp copy', 'libfs::common')
            os.utime(outfd, ns=(st.st_atime_ns, st.st_mtime_ns))

    def regular(self, source, target, metadata):
        infd = outfd = None
        phase = 'dispatch'
        try:
            self.backup(target)
            infd = os.open(source, os.O_RDONLY)
            st = os.fstat(infd)
            outfd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
            os.ftruncate(outfd, st.st_size)
            reflinked = False
            if self.opts['reflink'] != 'never':
                left = self.file_description(infd, source, True)
                right = self.file_description(outfd, target, False)
                self.debug_copy('Attempting reflink from ' + left + '->' + right)
                try:
                    fcntl.ioctl(outfd, 0x40049409, infd)  # Linux FICLONE
                    reflinked = True
                except OSError:
                    if self.opts['reflink'] == 'always':
                        raise CopyFailure("Failed to reflink file and 'always' was specified: " + left + '->' + right, 'dispatch')
                if reflinked:
                    self.debug_copy('Reflink ' + right + ' succeeded')
                    if self.parblock:
                        self.log.info('Reflinked, skipping rest of copy')
            phase = 'copy'
            if not reflinked:
                self.data_copy(infd, outfd, st)
            phase = 'dispatch'
            self.attributes(infd, outfd, st)
            if self.flag('fsync'):
                os.fsync(outfd)
        except OSError as e:
            raise CopyFailure(os_error(e), phase)
        finally:
            if outfd is not None:
                os.close(outfd)
            if infd is not None:
                os.close(infd)

    def perform(self, op):
        kind, source, target, metadata = op
        if not self.parblock and not self.worker_started:
            workers = min(self.opts['workers'] or os.cpu_count() or 1, 64)
            for thread in range(4, 4+workers):
                self.log.debug(thread, 'libxcp::drivers::parfile', 'Starting copy worker ThreadId({})'.format(thread))
            self.worker_started = True
        if not self.parblock:
            self.debug_copy('Received operation {}({}, {})'.format(kind, quoted(source), quoted(target)), 'libxcp::drivers::parfile')
        if kind == 'Special':
            display = 'Special'
        else:
            display = kind
        self.log.info('{}[ThreadId({})]: {} {} -> {}'.format('Dispatch' if self.parblock else 'Worker', self.copy_thread, display, quoted(source), quoted(target)))
        try:
            if kind == 'Copy':
                self.regular(source, target, metadata)
            elif kind == 'Symlink':
                try:
                    os.symlink(source, target)
                except OSError:
                    pass  # Failed symlink creation is intentionally nonfatal.
            else:
                try:
                    if os.path.lexists(target):
                        os.unlink(target)
                    os.mknod(target, metadata.st_mode, metadata.st_rdev)
                except OSError as e:
                    raise CopyFailure(os_error(e))
        except CopyFailure as e:
            if self.parblock:
                if e.phase == 'copy':
                    self.log.line('ERROR', 'Error copying: aborting.')
                else:
                    self.log.line('ERROR', 'Dispatcher: Error copying {} -> {}.'.format(quoted(source), quoted(target)))
            else:
                self.log.line('ERROR', 'Error copying: {} -> {}; aborting.'.format(quoted(source), quoted(target)))
            message = 'Error during copy: ' + e.detail
            self.log.line('ERROR', 'Received error: ' + message)
            fatal(message)

    def run(self, sources, dest):
        pairs = self.preflight(sources, dest)
        self.debug_walk('Starting walk worker ThreadId({})'.format(self.walk_thread))
        for source, target in pairs:
            self.walk(source, target)
        self.debug_walk('Walk-worker finished: ThreadId({})'.format(self.walk_thread))
        if self.parblock:
            self.log.info('Queuing complete')
            self.log.info('Pool complete')
        else:
            workers = min(self.opts['workers'] or os.cpu_count() or 1, 64)
            for thread in range(4, 4+workers):
                self.log.debug(thread, 'libxcp::drivers::parfile', 'Copy worker ThreadId({}) shutting down'.format(thread))
        self.log.info('Copy complete')


def main():
    try:
        parser = Parser(os.path.basename(sys.argv[0]) or 'executable')
        options, paths = parser.parse(sys.argv[1:])
        copier = Copier(options)
        if options['reflink'] == 'never':
            copier.log.line('WARN', '--reflink=never is selected, however the Linux kernel may override this.')
        if options.get('force') and options.get('no-clobber'):
            fatal('Invalid arguments: --force and --noclobber cannot be set at the same time.')
        if 'target-directory' in options:
            dest = options['target-directory']
        elif not paths:
            fatal('Invalid arguments: Insufficient arguments')
        else:
            dest = paths.pop()
        sources = []
        if options.get('glob'):
            for pattern in paths:
                sources.extend(expand_glob(pattern))
        else:
            sources = paths
        copier.run(sources, dest)
        return 0
    except Exit as e:
        return e.code
    except BrokenPipeError:
        return 1
    except KeyboardInterrupt:
        return 130
    except OSError as e:
        write('Error: ' + os_error(e) + '\n', sys.stderr)
        return 1


if __name__ == '__main__':
    sys.exit(main())
