import math
import os
import re
import sys
import time

RESET = '\x1b[0m'


def supports_color(stream):
    if os.environ.get('NO_COLOR') or os.environ.get('TERM') == 'dumb':
        return False
    if os.environ.get('CLICOLOR_FORCE', '0') not in ('', '0'):
        return True
    return stream.isatty()


def style(text, code):
    return '\x1b[' + code + 'm' + text + RESET


def usage_color(text, program):
    text = text.replace('Usage:', style('Usage:', '1m\x1b[4'), 1)
    text = text.replace(' ' + program, ' ' + style(program, '1'), 1)
    text = re.sub(r'--[A-Za-z][A-Za-z-]*(?:\.\.\.)?', lambda m: style(m[0], '1'), text)
    return text


def help_color(text, program):
    result = []
    for line in text.splitlines(keepends=True):
        if line.startswith('Usage:'):
            line = usage_color(line, program)
        elif line.rstrip('\n') in ('Arguments:', 'Options:'):
            line = style(line.rstrip('\n'), '1m\x1b[4') + '\n'
        elif re.match(r'^ {2,6}-', line):
            line = re.sub(r'--[A-Za-z-]+|-[A-Za-z]', lambda m: style(m[0], '1'), line)
        result.append(line)
    return ''.join(result)


def error_color(text, program):
    lines = text.splitlines(keepends=True)
    for i, line in enumerate(lines):
        if line.startswith('error:'):
            # The first quotation denotes an offending argument/value. A
            # second 'for' quotation describes the option's expected type.
            line = re.sub(r"'([^']*)'", lambda m: "'" + style(m[1], '33') + "'", line, count=1)
            line = re.sub(r" for '([^']*)'", lambda m: " for '" + style(m[1], '1') + "'", line)
            line = line.replace('error:', style('error:', '1m\x1b[31'), 1)
        elif line.startswith('Usage:'):
            line = usage_color(line, program)
        elif line.startswith('  tip:'):
            line = line.replace('tip:', style('tip:', '32'), 1)
            if 'to pass' in line:
                line = re.sub(r"'([^']*)'", lambda m: "'" + style(m[1], '33') + "'", line, count=1)
                line = re.sub(r"use '([^']*)'", lambda m: "use '" + style(m[1], '32') + "'", line)
            else:
                line = re.sub(r"'([^']*)'", lambda m: "'" + style(m[1], '32') + "'", line)
        elif line.startswith('For more information'):
            line = line.replace('--help', style('--help', '1'))
        lines[i] = line
    return ''.join(lines)


def human_bytes(count):
    if count < 1024:
        return str(int(count)) + ' B'
    value = float(count)
    units = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB']
    idx = 0
    while value >= 1024 and idx < len(units)-1:
        value /= 1024
        idx += 1
    return '{:.2f} {}'.format(value, units[idx])


class Progress:
    def __init__(self, disabled):
        self.enabled = not disabled and sys.stderr.isatty()
        self.started = False
        self.total = 0
        self.position = 0
        self.begin = time.monotonic()
        self.rows = 0
        self.width = 80
        self.multiline = False
        if self.enabled:
            try:
                width = os.get_terminal_size(sys.stderr.fileno()).columns
            except OSError:
                width = 0
            self.width = width or 80
            self.multiline = 0 < width < 150

    def start(self, amount):
        if not self.enabled:
            return
        self.total += amount
        if not self.started:
            self.started = True
            self.begin = time.monotonic()
            self.draw(False)

    def advance(self, amount):
        self.position += amount

    def clear(self):
        if not self.rows:
            return
        if self.rows == 1:
            sys.stderr.write('\r\x1b[2K')
        else:
            up = '\x1b[{}A'.format(self.rows-1)
            sys.stderr.write(up + '\r\x1b[2K' + '\x1b[1B\r\x1b[2K'*(self.rows-1) + up)

    def draw(self, final):
        position = self.total if final else self.position
        percent = int(100*position/self.total) if self.total else 100
        bar_width = max(0, self.width-(2 if self.multiline else 72))
        filled = int(bar_width*percent/100)
        if supports_color(sys.stderr):
            bar = '[\x1b[36m' + '#'*filled + '\x1b[34m' + '-'*(bar_width-filled) + RESET + RESET + ']'
        else:
            bar = '[' + '#'*filled + '-'*(bar_width-filled) + ']'
        elapsed = time.monotonic()-self.begin
        speed = human_bytes(position/elapsed if elapsed and position else 0) + '/s'
        if not final:
            speed = '0 B/s'
        status = '{:>11} / {:<11} | {:3}% | {:^13} | 00:00:00 remaining'.format(
            human_bytes(position), human_bytes(self.total), percent, speed)
        self.clear()
        if self.multiline:
            status_rows = max(1, math.ceil(len(status)/self.width))
            sys.stderr.write(bar + '\n' + status.ljust(status_rows*self.width))
            self.rows = 1+status_rows
        else:
            sys.stderr.write(bar + ' ' + status)
            self.rows = 1
        sys.stderr.flush()

    def finish(self):
        if self.enabled:
            self.draw(True)
